struct Entry {
    args: CreateMarketArgs,
    symbol: String,
    source: u8,
}

fn num<T: FromStr>(v: &Value) -> T
where
    T::Err: std::fmt::Debug,
{
    v.as_str().unwrap_or_else(|| panic!("{v} is not a decimal string")).parse().expect("decimal integer")
}

fn arr<T: FromStr + Copy + Default, const N: usize>(v: &Value) -> [T; N]
where
    T::Err: std::fmt::Debug,
{
    let a = v.as_array().expect("array");
    assert_eq!(a.len(), N);
    let mut out = [T::default(); N];
    for (o, x) in out.iter_mut().zip(a) {
        *o = num(x);
    }
    out
}

fn hex32(s: &str) -> [u8; 32] {
    assert_eq!(s.len(), 64);
    let mut out = [0u8; 32];
    for (k, b) in out.iter_mut().enumerate() {
        *b = u8::from_str_radix(&s[2 * k..2 * k + 2], 16).expect("hex");
    }
    out
}

fn load() -> (Vec<Entry>, RuleSetArgs) {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../config/launch.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let v: Value = serde_json::from_str(&text).expect("launch.json is JSON");
    assert_eq!((v["format"].as_str(), v["version"].as_str()), (Some("setl8-launch"), Some("1")));
    let markets = v["markets"]
        .as_array()
        .expect("markets")
        .iter()
        .map(|m| {
            let p = &m["params"];
            let mut sessions = [Session::default(); 6];
            for (slot, w) in sessions.iter_mut().zip(p["sessions"].as_array().expect("sessions")) {
                *slot = Session { start_min: num(&w[0]), end_min: num(&w[1]) };
            }
            Entry {
                args: CreateMarketArgs {
                    market_id: num(&m["market_id"]),
                    class: num(&m["class"]),
                    params: MarketParams {
                        status: num(&p["status"]),
                        feed_id: hex32(p["feed_id"].as_str().expect("feed_id")),
                        max_age_secs: num(&p["max_age_secs"]),
                        qty_step: num(&p["qty_step"]),
                        qty_min: num(&p["qty_min"]),
                        max_notional_usd: num(&p["max_notional_usd"]),
                        session_count: num(&p["session_count"]),
                        sessions,
                        quote_conv_market: num(&p["quote_conv_market"]),
                    },
                },
                symbol: m["meta"]["symbol"].as_str().expect("symbol").to_string(),
                source: num(&m["meta"]["source"]),
            }
        })
        .collect();
    let r = &v["ruleset"];
    let ruleset = RuleSetArgs {
        version: num(&r["version"]),
        fee_bps: num(&r["fee_bps"]),
        tier_count: num(&r["tier_count"]),
        ladder_len: num(&r["ladder_len"]),
        leverage_x: arr(&r["leverage_x"]),
        holding_fee_e6: arr(&r["holding_fee_e6"]),
        commission_e6: arr(&r["commission_e6"]),
        tier_size: arr(&r["tier_size"]),
        tier_cost: arr(&r["tier_cost"]),
        reset_ladder_bps: arr(&r["reset_ladder_bps"]),
        spread_e6: arr(&r["spread_e6"]),
    };
    (markets, ruleset)
}

fn bytes<T: AnchorSerialize>(x: &T) -> Vec<u8> {
    x.try_to_vec().expect("borsh")
}

/// A fresh vault harness with our program initialised, NO markets and NO rule set: the state right after `init_config`.
fn fresh(ruleset: &RuleSetArgs) -> VaultEnv {
    VaultEnv::with(Opts { ruleset: ruleset.clone(), skip_ruleset: true, ..Opts::default() })
}

#[test]
fn the_file_is_shaped_as_the_instructions_need_it() {
    let (markets, ruleset) = load();
    assert_eq!(markets.len(), 21);
    // ids sequential from 0, every conversion market is NO_QUOTE_CONV (all prices are USD), status enabled
    for (k, m) in markets.iter().enumerate() {
        assert_eq!(usize::from(m.args.market_id), k);
        assert_eq!(m.args.params.quote_conv_market, c::NO_QUOTE_CONV, "{}", m.symbol);
        assert_eq!(m.args.params.status, 1, "{}", m.symbol);
        assert!(usize::from(m.args.class) < c::CLASS_COUNT);
    }
    // unique feed ids, unique symbols
    assert_eq!(markets.iter().map(|m| m.args.params.feed_id).collect::<BTreeSet<_>>().len(), 21);
    assert_eq!(markets.iter().map(|m| m.symbol.clone()).collect::<BTreeSet<_>>().len(), 21);
    // every feed id is the documented hash of its source and symbol
    for m in &markets {
        assert_eq!(m.args.params.feed_id, journal_types::feed_id(&journal_types::NativeSha256, m.source, &m.symbol), "{}", m.symbol);
    }
    // unique, ascending tier sizes (the program also requires it)
    let sizes = &ruleset.tier_size[..usize::from(ruleset.tier_count)];
    assert_eq!(sizes.iter().collect::<BTreeSet<_>>().len(), sizes.len());
    assert!(sizes.windows(2).all(|w| w[0] < w[1]));
    // the rule set is the launch rule set of the test harness in everything but the spreads and the commissions
    let launch = launch_ruleset_args();
    let strip = |r: &RuleSetArgs| RuleSetArgs { commission_e6: [0; 8], spread_e6: [0; 128], ..r.clone() };
    assert_eq!(bytes(&strip(&ruleset)), bytes(&strip(&launch)), "tiers, costs, ladder, leverage, holding fee and fee are DESIGN 5.4");
    // every market has a half-spread; none beyond the last id has one
    assert!(ruleset.spread_e6[..21].iter().all(|s| *s > 0));
    assert!(ruleset.spread_e6[21..].iter().all(|s| *s == 0));
}

#[test]
fn the_file_loads_through_the_real_instructions_in_deploy_order_and_the_chain_equals_the_file() {
    let (markets, ruleset) = load();
    let mut v = fresh(&ruleset);
    assert_eq!((v.e.config().market_count, v.e.config().current_ruleset), (0, 0));
    for (k, m) in markets.iter().enumerate() {
        v.e.create_market_ok(&m.args);
        assert_eq!(usize::from(v.e.config().market_count), k + 1);
    }
    assert_eq!(v.e.config().current_ruleset, 0, "the rule set comes AFTER the markets");
    v.e.create_ruleset_ok(&ruleset);
    assert_eq!(v.e.config().current_ruleset, 1);
    for m in &markets {
        let on_chain = v.e.market(m.args.market_id);
        let p = &m.args.params;
        assert_eq!((on_chain.market_id, on_chain.class, on_chain.status, on_chain.feed_id), (m.args.market_id, m.args.class, p.status, p.feed_id), "{}", m.symbol);
        assert_eq!((on_chain.max_age_secs, on_chain.qty_step, on_chain.qty_min, on_chain.max_notional_usd), (p.max_age_secs, p.qty_step, p.qty_min, p.max_notional_usd), "{}", m.symbol);
        assert_eq!((on_chain.session_count, on_chain.quote_conv_market), (p.session_count, p.quote_conv_market), "{}", m.symbol);
        assert_eq!(bytes(&on_chain.sessions), bytes(&p.sessions), "{}", m.symbol);
    }
    let rs = v.e.ruleset(1);
    assert_eq!((rs.version, rs.fee_bps, rs.tier_count, rs.ladder_len), (1, 40, 10, 5));
    assert_eq!(bytes(&(rs.leverage_x, rs.holding_fee_e6, rs.commission_e6, rs.tier_size, rs.tier_cost, rs.reset_ladder_bps)), bytes(&(ruleset.leverage_x, ruleset.holding_fee_e6, ruleset.commission_e6, ruleset.tier_size, ruleset.tier_cost, ruleset.reset_ladder_bps)));
    assert_eq!(bytes(&rs.spread_e6), bytes(&ruleset.spread_e6));
    // the ids are sequential: a 22nd market must take id 21, and the file's ids cannot be created twice
    let again = markets[3].args.clone();
    assert!(v.e.send_admins(create_market_ix(v.e.payer.pubkey(), Admins::both(&v.e), &again), Admins::both(&v.e)).is_err());
}

const BTC: u16 = 0;
const JP225: u16 = 9;
const AAPL: u16 = 11;
const MONDAY: i64 = ::evaluator::testkit::MONDAY;

fn price(usd: f64) -> u64 {
    (usd * 1e12).round() as u64
}

/// One session of 120 seconds in market `id`: a sample every 5 s (the price alternates by 1 bp, so it keeps changing), a
/// market buy at +30 s, the close at +70 s, a posting at +125 s.
fn block(steps: &mut Vec<Step>, nonce: &mut u32, id: u16, t0: i64, px: u64, qty: u64) {
    for k in 0..=24i64 {
        let sec = t0 + 5 * k;
        steps.push(Step::Sample { market: id, sec, mid: if k % 2 == 0 { px } else { px + px / 10_000 } });
        let intent = |kind, side, qty| OrderIntent { kind, market: id, side, qty, price_e12: 0, sl_e12: 0, tp_e12: 0, target_nonce: 0, client_time: sec };
        if k == 6 {
            steps.push(Step::Order { nonce: *nonce, intent: intent(IntentKind::Market, 0, qty) });
            *nonce += 1;
        }
        if k == 14 {
            steps.push(Step::Order { nonce: *nonce, intent: intent(IntentKind::Close, 0, 0) });
            *nonce += 1;
        }
    }
    steps.push(Step::Post { sec: t0 + 125, heartbeat: false });
}

#[test]
fn an_account_opened_under_the_launch_rule_set_trades_three_launch_markets_and_the_verifier_says_valid() {
    let (markets, ruleset) = load();
    let mut v = fresh(&ruleset);
    for m in &markets {
        v.e.create_market_ok(&m.args);
    }
    v.e.create_ruleset_ok(&ruleset);

    // the evaluator's view of the same 21 markets: only the three that are traded get samples
    let usd = |symbol: &str| match symbol {
        "BTC" => 81_131.526567,
        "xyz:JP225" => 63_898.0,
        "xyz:AAPL" => 340.86,
        _ => 100.0,
    };
    let specs: Vec<MarketSpec> = markets
        .iter()
        .map(|m| {
            let p = &m.args.params;
            let sessions = p.sessions[..usize::from(p.session_count)].iter().map(|s| (s.start_min, s.end_min)).collect();
            let mut spec = MarketSpec::plain(m.args.market_id, m.args.class, m.symbol.clone(), m.source, price(usd(&m.symbol)), p.max_age_secs, u32::from(ruleset.spread_e6[usize::from(m.args.market_id)]), sessions);
            spec.qty_step = p.qty_step;
            spec.qty_min = p.qty_min;
            spec.max_notional_micro = p.max_notional_usd;
            spec
        })
        .collect();
    // the hours of the three markets: BTC 24/7, JP225 Monday 00:00 to 06:00 UTC, AAPL Monday 14:30 to 20:00 UTC
    let (t_btc, t_jp, t_aapl) = (MONDAY + 600, MONDAY + 4_200, MONDAY + 54_000);
    let mut steps = Vec::new();
    let mut nonce = 1u32;
    block(&mut steps, &mut nonce, BTC, t_btc, price(usd("BTC")), 1_000);
    block(&mut steps, &mut nonce, JP225, t_jp, price(usd("xyz:JP225")), 2_000);
    block(&mut steps, &mut nonce, AAPL, t_aapl, price(usd("xyz:AAPL")), 100_000);
    let end = t_aapl + 140;
    steps.push(Step::Post { sec: end, heartbeat: true });
    let spec = PathSpec {
        seed: 0,
        scenario: Scenario::Noise,
        tier: 8,
        size_micro: 100_000_000_000,
        phase: 1,
        opened_time: MONDAY + 300,
        markets: specs,
        commission_e6: ruleset.commission_e6,
        steps,
        batch_max_events: 8,
        end,
    };

    let mut chain = LiteChain::from_vault(&spec, v);
    let world = World::from_params(spec_rules(&spec), chain.params.clone());
    let r = run_path(&spec, world, &mut chain);
    // the history was traded: a buy and a close on each of the three markets
    let evs = events(&r.items);
    for id in [BTC, JP225, AAPL] {
        let fills = evs.iter().filter(|e| matches!(e, JournalEvent::Fill { market, .. } if *market == id)).count();
        let closes = evs.iter().filter(|e| matches!(e, JournalEvent::Close { market, .. } if *market == id)).count();
        assert_eq!((fills, closes), (1, 1), "market {id}");
    }
    assert!(r.world.ev.refusals().is_empty(), "{:?}", r.world.ev.refusals());
    // posted to the real program, compared byte for byte after every transaction, and judged by the public verifier
    verify_segment(&spec, &chain, &r).unwrap_or_else(|e| panic!("{e}"));
    // the sources: GMX, Hyperliquid index, Hyperliquid stock
    assert_eq!(spec.markets.iter().filter(|m| [BTC, JP225, AAPL].contains(&m.id)).map(|m| m.source).collect::<Vec<_>>(), vec![2, 4, 4]);
}

#[test]
fn the_sessions_of_the_file_decide_open_and_closed_with_the_programs_own_function() {
    // journal_types::in_session is what the program, the evaluator and the verifier all use (decision 49)
    let (markets, _) = load();
    let open = |id: u16, t: i64| {
        let p = &markets[usize::from(id)].args.params;
        let w: Vec<(u16, u16)> = p.sessions.iter().map(|s| (s.start_min, s.end_min)).collect();
        journal_types::in_session(&w, p.session_count, t)
    };
    let day = 86_400;
    // JP225: Monday to Friday 00:00-06:00 UTC
    assert!(open(JP225, MONDAY + 4_200) && !open(JP225, MONDAY + 54_000) && !open(JP225, MONDAY + 6 * 3_600));
    assert!(open(JP225, MONDAY + 6 * 3_600 - 1) && open(JP225, MONDAY + 4 * day + 60) && !open(JP225, MONDAY + 5 * day + 60));
    // AAPL: Monday to Friday 14:30-20:00 UTC
    assert!(open(AAPL, MONDAY + 14 * 3_600 + 30 * 60) && !open(AAPL, MONDAY + 14 * 3_600 + 29 * 60) && !open(AAPL, MONDAY + 20 * 3_600) && open(AAPL, MONDAY + 20 * 3_600 - 1));
    // BTC: always
    assert!(open(BTC, MONDAY) && open(BTC, MONDAY + 5 * day + 12 * 3_600) && open(BTC, MONDAY + 7 * day - 1));
    // GOLD: the Sunday evening window ends exactly at the week end and the week starts open until Monday 21:00
    let gold = 3u16;
    assert!(open(gold, MONDAY + 6 * day + 23 * 3_600) && open(gold, MONDAY + 7 * day - 1) && open(gold, MONDAY) && open(gold, MONDAY + 21 * 3_600 - 1));
    assert!(!open(gold, MONDAY + 21 * 3_600) && !open(gold, MONDAY + 22 * 3_600 + 59 * 60) && open(gold, MONDAY + 23 * 3_600));
    assert!(!open(gold, MONDAY + 5 * day) && !open(gold, MONDAY + 6 * day + 22 * 3_600));
}

/// THE FINDING behind "Adding a market after launch" in launch.md (P19 point 7), as an executable path: an account of rule set
/// v1 trades a market created AFTER v1, at a ZERO half-spread, and nothing refuses it: the program accepts the fills (the market
/// account is global; `spread_e6[id]` of v1 is 0 for an id that did not exist), the evaluator trades what it is configured with, and
/// the verifier reads the missing spread as 0, so all three agree.
#[test]
fn an_old_account_trades_a_market_created_after_its_rule_set_at_zero_spread() {
    let (markets, ruleset) = load();
    let mut v = fresh(&ruleset);
    for m in &markets {
        v.e.create_market_ok(&m.args);
    }
    v.e.create_ruleset_ok(&ruleset);
    let new_id = 21u16;
    assert_eq!(ruleset.spread_e6[usize::from(new_id)], 0, "rule set v1 knows no market 21");

    let mut spec = PathSpec {
        seed: 0,
        scenario: Scenario::Noise,
        tier: 8,
        size_micro: 100_000_000_000,
        phase: 1,
        opened_time: MONDAY + 300,
        markets: vec![],
        commission_e6: [0; 8],
        steps: vec![],
        batch_max_events: 8,
        end: 0,
    };
    // the account is opened under v1 BEFORE the market exists
    let mut chain = LiteChain::from_vault(&spec, v);
    // then an admin adds market 21 (nothing needs a new rule set for that)
    let mut sessions = [Session::default(); 6];
    sessions[0] = Session { start_min: 0, end_min: 10_080 };
    chain.j.v.e.create_market_ok(&CreateMarketArgs {
        market_id: new_id,
        class: 6,
        params: MarketParams {
            status: 1,
            feed_id: journal_types::feed_id(&journal_types::NativeSha256, 2, "NEWCOIN"),
            max_age_secs: 15,
            qty_step: 1_000,
            qty_min: 1_000,
            max_notional_usd: 50_000_000_000,
            session_count: 1,
            sessions,
            quote_conv_market: c::NO_QUOTE_CONV,
        },
    });
    let px = price(100.0);
    spec.markets = vec![MarketSpec::plain(new_id, 6, "NEWCOIN".into(), 2, px, 15, 0, vec![(0, 10_080)])];
    let mut nonce = 1u32;
    block(&mut spec.steps, &mut nonce, new_id, MONDAY + 600, px, 10_000);
    spec.end = MONDAY + 740;
    spec.steps.push(Step::Post { sec: spec.end, heartbeat: true });

    let world = World::from_params(spec_rules(&spec), chain.params.clone());
    let r = run_path(&spec, world, &mut chain);
    // the program took the fill and the close, the evaluator's account equals the chain's after every transaction, the verifier says VALID
    verify_segment(&spec, &chain, &r).unwrap_or_else(|e| panic!("{e}"));
    let fill_price = events(&r.items).iter().find_map(|e| match e {
        JournalEvent::Fill { market, price_e12, .. } if *market == new_id => Some(*price_e12),
        _ => None,
    });
    // a buy at ask = mid x (1 + 0): the fill is at the sampled price itself (the sample alternates by 1 bp; k = 6 is the base price)
    assert_eq!(fill_price, Some(px), "bought at the mid: half-spread 0");
    // for contrast, a launch market pays its half-spread: BTC at 150 e6 is 1.5 bp above the mid
    assert!(ruleset.spread_e6[usize::from(BTC)] > 0);
}
